import json
with open('/app/resources/treasury_bulletin_1992_06.json', 'r') as f:
    data = json.load(f)

# Search through all content for 8703
def search_elements(elements, target):
    results = []
    for elem in elements:
        if isinstance(elem, dict):
            if elem.get('content') and target in str(elem.get('content')):
                results.append(elem.get('content'))
            # Check nested
            if 'elements' in elem:
                results.extend(search_elements(elem['elements'], target))
    return results

# The elements are in data['document']['elements']
results = search_elements(data.get('document', {}).get('elements', []), '8703')
for r in results:
    print(r[:500])
"

