import json
with open('/app/resources/treasury_bulletin_1992_06.json', 'r') as f:
    data = json.load(f)

# Let's look for any element containing 'National Bureau' or 'NBER'
def search_elements(elements, target):
    results = []
    for elem in elements:
        if isinstance(elem, dict):
            if elem.get('content') and target.lower() in str(elem.get('content')).lower():
                results.append(elem.get('content'))
            if 'elements' in elem:
                results.extend(search_elements(elem['elements'], target))
    return results

results = search_elements(data.get('document', {}).get('elements', []), 'NBER')
for r in results[:20]:
    print(r[:300])
"
